// Editable text uses a bounded local box and an affine transform. No network fonts.
export const textFonts=Object.freeze(['sans-serif','serif','monospace']);
const finite=n=>typeof n==='number'&&Number.isFinite(n),fail=m=>{throw Error(m);};
export function validateText(s){const t=s.text;if(!t||Object.keys(t).sort().join(',')!=='align,bold,content,font,fontSize,height,italic,transform,width'||typeof t.content!=='string'||!t.content.trim()||t.content.length>2048||t.content.split('\n').length>32||/[\u0000-\u0008\u000b-\u001f\u007f]/.test(t.content)||!textFonts.includes(t.font)||!finite(t.fontSize)||t.fontSize<8||t.fontSize>256||!['left','center','right'].includes(t.align)||typeof t.bold!=='boolean'||typeof t.italic!=='boolean'||![t.width,t.height].every(n=>finite(n)&&n>=1&&n<=1024)||!Array.isArray(t.transform)||t.transform.length!==6||!t.transform.every(finite)||Math.abs(t.transform[0]*t.transform[3]-t.transform[1]*t.transform[2])<1e-8||t.transform.some(n=>Math.abs(n)>1e7)||s.size!==1||s.points.length!==5||['preset','dynamics','recipe','raster'].some(k=>Object.hasOwn(s,k)))fail('Invalid or oversized text');const expected=textPoints(t);if(!s.points.every((q,i)=>q.pressure===null&&Math.abs(q.x-expected[i].x)<1e-6&&Math.abs(q.y-expected[i].y)<1e-6))fail('Text bounds do not match transform');}
export function textFont(t){return `${t.italic?'italic ':''}${t.bold?'bold ':''}${t.fontSize}px ${t.font}`;}
export function textPoints(t){const [a,b,c,d,e,f]=t.transform;return [[0,0],[t.width,0],[t.width,t.height],[0,t.height],[0,0]].map(([x,y])=>({x:a*x+c*y+e,y:b*x+d*y+f,pressure:null}));}
export function transformText(s,m){const t=s.text,[a,b,c,d,e,f]=m,[u,v,w,z,x,y]=t.transform;t.transform=[a*u+c*v,b*u+d*v,a*w+c*z,b*w+d*z,a*x+c*y+e,b*x+d*y+f];s.points=textPoints(t);}
export function textContains(s,p){const t=s.text,[a,b,c,d,e,f]=t.transform,det=a*d-b*c,x=(d*(p.x-e)-c*(p.y-f))/det,y=(-b*(p.x-e)+a*(p.y-f))/det;return x>=0&&y>=0&&x<=t.width&&y<=t.height;}
export function makeText({content,font='sans-serif',fontSize=32,bold=false,italic=false,align='left',color='#203d48',opacity=1,transform=[1,0,0,1,0,0]},measure){content=content.replace(/\r\n?/g,'\n');const t={content,font,fontSize,bold,italic,align,transform:[...transform],width:1,height:1};const lines=content.split('\n');const widths=lines.map(line=>measure(line,textFont(t)));t.width=Math.ceil(Math.max(1,...widths)+fontSize*.5+8);t.height=Math.ceil(lines.length*fontSize*1.4+8);const s={id:crypto.randomUUID(),brush:'text',color,size:1,opacity,points:textPoints(t),text:t};validateText(s);return s;}
export function drawText(ctx,s){const t=s.text;ctx.save();try{ctx.transform(...t.transform);ctx.beginPath();ctx.rect(0,0,t.width,t.height);ctx.clip();ctx.font=textFont(t);ctx.fillStyle=s.color;ctx.globalAlpha=1;ctx.textBaseline='alphabetic';ctx.textAlign=t.align;const pad=t.fontSize*.25+4,x=t.align==='left'?pad:t.align==='center'?t.width/2:t.width-pad;t.content.split('\n').forEach((line,i)=>ctx.fillText(line,x,4+t.fontSize+i*t.fontSize*1.4,Math.max(1,t.width-pad*2)));}finally{ctx.restore();}}
